export function deserializeWorkspaceState(
  workspaceId: string,
  persistedSession: PersistedWorkspaceSession,
  liveBackendSessionIds?: Iterable<string | { sessionId: string; daemonEpoch?: string | null }> | null,
): WorkspaceState | null {
  const ws = persistedSession.workspaces?.[workspaceId];
  if (!ws) return null;
  const isV2 = (persistedSession.version ?? 1) >= 2;

  const browserSettings = loadBrowserSettings();
  const restoreBrowser = browserSettings.restoreTabsOnLaunch;
  const knownProfiles = new Set(browserSettings.profiles.map((p) => p.id));
  const fallbackProfileId = browserSettings.defaultProfileId;

  const liveEpochMap = new Map<string, string | null>();
  const liveSet = new Set<string>();
  if (liveBackendSessionIds) {
    for (const item of liveBackendSessionIds) {
      if (typeof item === "string") {
        liveSet.add(item);
      } else if (item && typeof item === "object" && "sessionId" in item) {
        liveSet.add(item.sessionId);
        if (item.daemonEpoch !== undefined) {
          liveEpochMap.set(item.sessionId, item.daemonEpoch ?? null);
        }
      }
    }
  }

  const worktrees: Worktree[] = (ws.worktrees || []).map((wt) => ({
    path: wt.path,
    branch: wt.branch ? (wt.branch.startsWith("refs/heads/") ? wt.branch : `refs/heads/${wt.branch}`) : null,
    head: wt.head,
    bare: false,
    detached: false,
    locked: wt.isLocked ? "locked" : null,
    prunable: null,
  }));

  const sessions: Record<string, TerminalSession> = {};
  for (const [mapKey, sess] of Object.entries(ws.terminalSessions || {})) {
    const localSessionId = sess.localSessionId || mapKey || sess.sessionId || "";
    if (!localSessionId) continue;
    const persistedBackendSessionId = isV2 ? (sess.backendSessionId ?? null) : (sess.backendSessionId ?? sess.sessionId ?? null);
    const hasLiveBackend = liveBackendSessionIds
      ? (persistedBackendSessionId ? liveSet.has(persistedBackendSessionId) : false)
      : Boolean(persistedBackendSessionId);

    let isEpochMatched = true;
    if (persistedBackendSessionId && liveEpochMap.has(persistedBackendSessionId)) {
      const liveEpoch = liveEpochMap.get(persistedBackendSessionId);
      if (sess.daemonEpoch && liveEpoch && sess.daemonEpoch !== liveEpoch) {
        isEpochMatched = false;
      }
    }

    const backendSessionId = hasLiveBackend && isEpochMatched ? persistedBackendSessionId : null;
    const daemonEpoch = backendSessionId ? (sess.daemonEpoch ?? null) : null;
    const lastOutputSequence = backendSessionId ? (sess.lastOutputSequence ?? null) : null;
    const worktreePath = sess.worktreePath || sess.cwd;
    const matchingWorktree = worktrees.find((wt) => wt.path === worktreePath);
    sessions[localSessionId] = {
      id: localSessionId,
      cwd: sess.cwd || worktreePath,
      worktreePath,
      workspaceId,
      worktree: matchingWorktree ? worktreeIdentity(matchingWorktree) : null,
      backendSessionId,
      lifecycle: backendSessionId ? "working" : "exited",
      daemonEpoch,
      lastOutputSequence,
    };
  }

